        for k,x in enumerate(a): out[h-len(a)+k][j]=x
    return out"},{"nl":"Move every nonzero cell upward within its column as far as possible, preserving order.","code":"def transform(grid):
    h,w=len(grid),len(grid[0]); out=[[0]*w for _ in range(h)]
