        c=Counter(grid[i][j] for i in range(h) if grid[i][j]); v=c.most_common(1)[0][0] if c else 0
        for i in range(h):
            if grid[i][j]: out[i][j]=v
    return out"},{"nl":"Fill every zero cell horizontally between the leftmost and rightmost nonzero cells in its row with the row's nearest nonzero color.","code":"def transform(grid):
    out=[r[:] for r in grid]
